module.testfuncsCs:
"""Ersatz fuer das CodeExpert-interne Modul 'testfuncsCs'.

ACHTUNG: Dieses Modul liegt dem Kursmaterial NICHT bei. Es ist hier
nachgebaut, damit die Original-Aufgabe ueberhaupt laufen kann. Die
Aufgabenstellung und der zu ergaenzende Code sind unveraendert; nur die
fuenf Testfunktionen sind eigene, aber in der Glattheit gestaffelte Wahl:
analytisch, Runge (analytisch mit nahen Polen), C^3, C^1 und nur stetig.
"""
import numpy as np


def create_test_functions(interval=(0.0, 1.0)):
    """Gibt (Liste von (f, df, name), interval) zurueck.

    Alle Funktionen sind ueber u = 2*(x-a)/(b-a) - 1 in [-1, 1] definiert;
    die Kettenregel liefert den Faktor du/dx = 2/(b-a).
    """
    a, b = float(interval[0]), float(interval[1])
    s = 2.0 / (b - a)

    def u(x):
        return s * (np.asarray(x, dtype=float) - a) - 1.0

    def f_an(x):
        return np.exp(u(x)) * np.cos(5.0 * u(x))

    def df_an(x):
        t = u(x)
        return s * np.exp(t) * (np.cos(5.0 * t) - 5.0 * np.sin(5.0 * t))

    def f_runge(x):
        return 1.0 / (1.0 + 25.0 * u(x) ** 2)

    def df_runge(x):
        t = u(x)
        return s * (-50.0 * t) / (1.0 + 25.0 * t ** 2) ** 2

    def f_c3(x):
        return np.abs(u(x)) ** 3.5

    def df_c3(x):
        t = u(x)
        return s * 3.5 * np.abs(t) ** 2.5 * np.sign(t)

    def f_c1(x):
        return np.abs(u(x)) ** 1.5

    def df_c1(x):
        t = u(x)
        return s * 1.5 * np.abs(t) ** 0.5 * np.sign(t)

    def f_c0(x):
        return np.abs(u(x))

    def df_c0(x):
        return s * np.sign(u(x))

    funcs = [
        (f_an,    df_an,    'analytic exp(u)cos(5u)'),
        (f_runge, df_runge, 'Runge 1/(1+25u^2)'),
        (f_c3,    df_c3,    'C^3 |u|^3.5'),
        (f_c1,    df_c1,    'C^1 |u|^1.5'),
        (f_c0,    df_c0,    'C^0 |u|'),
    ]
    return funcs, (a, b)

module.testfuncsSplines:
"""Ersatz fuer das CodeExpert-interne Modul 'testfuncsSplines'.

ACHTUNG: Dieses Modul liegt dem Kursmaterial NICHT bei. Nachgebaut, damit
die Original-Aufgabe laeuft. Wichtig fuer die Aufgabe ist nur, dass der
Name einer NICHT periodischen Funktion die Zeichenkette 'non-periodic'
enthaelt — der periodische Spline ueberspringt genau diese.
"""
import numpy as np

TWO_PI = 2.0 * np.pi


def create_test_functions(interval=(0.0, 1.0)):
    a, b = float(interval[0]), float(interval[1])

    def f_per_an(x):
        """1-periodisch und analytisch."""
        return np.exp(np.sin(TWO_PI * np.asarray(x, dtype=float)))

    def df_per_an(x):
        t = TWO_PI * np.asarray(x, dtype=float)
        return TWO_PI * np.cos(t) * np.exp(np.sin(t))

    def f_per_c3(x):
        """1-periodisch, aber nur C^3 (|sin|^3.5 hat an x=0 eine Spitze in
        der vierten Ableitung)."""
        return np.abs(np.sin(np.pi * np.asarray(x, dtype=float))) ** 3.5

    def df_per_c3(x):
        t = np.pi * np.asarray(x, dtype=float)
        return 3.5 * np.abs(np.sin(t)) ** 2.5 * np.sign(np.sin(t)) * np.pi * np.cos(t)

    def f_nonper(x):
        """non-periodic: exp(x)*cos(5x)."""
        x = np.asarray(x, dtype=float)
        return np.exp(x) * np.cos(5.0 * x)

    def df_nonper(x):
        x = np.asarray(x, dtype=float)
        return np.exp(x) * (np.cos(5.0 * x) - 5.0 * np.sin(5.0 * x))

    def f_nonper_runge(x):
        """non-periodic Runge."""
        u = 2.0 * (np.asarray(x, dtype=float) - a) / (b - a) - 1.0
        return 1.0 / (1.0 + 25.0 * u ** 2)

    def df_nonper_runge(x):
        s = 2.0 / (b - a)
        u = s * (np.asarray(x, dtype=float) - a) - 1.0
        return s * (-50.0 * u) / (1.0 + 25.0 * u ** 2) ** 2

    funcs = [
        (f_per_an,        df_per_an,        'periodic analytic exp(sin)'),
        (f_per_c3,        df_per_c3,        'periodic C^3 |sin|^3.5'),
        (f_nonper,        df_nonper,        'non-periodic exp(x)cos(5x)'),
        (f_nonper_runge,  df_nonper_runge,  'non-periodic Runge'),
    ]
    return funcs, (a, b)
